using System;
using System.Collections.Generic;
using System.Threading;
using Foundation.Content;
using Cysharp.Threading.Tasks;
using HybridCLR;
using UnityEngine;

namespace Foundation.Infrastructure.HybridClr
{
    /// <summary>
    /// Loads supplemental AOT metadata only for the stripped AOT dlls that hot-update generics need, never
    /// "every assembly, just in case". Pass the list generated by
    /// <c>HybridCLR/Generate/AOTGenericReference</c>; it lives in project code, so what is required is a
    /// project decision. Must run once before hot-update code that instantiates AOT generics;
    /// <see cref="EnsureLoadedAsync"/> is idempotent, so repeating the call is safe.
    /// </summary>
    public sealed class HybridClrAotMetadataPreloader
    {
        private readonly IAssetProvider _assetProvider;
        private readonly IReadOnlyList<string> _aotAssemblyAddresses;
        private readonly IHotUpdateAssemblyVerifier _verifier;
        private readonly IHotUpdateAssemblySource _assemblySource;
        private readonly SemaphoreSlim _loadGate = new(1, 1);
        private int _nextAssemblyIndex;

        public HybridClrAotMetadataPreloader(
            IAssetProvider assetProvider,
            IReadOnlyList<string> aotAssemblyAddresses,
            IHotUpdateAssemblyVerifier verifier = null,
            IHotUpdateAssemblySource assemblySource = null)
        {
            // Metadata carries the IL the interpreter runs for AOT generics, so it is verified like code when a verifier is given.
            _verifier = verifier;
            _assemblySource = assemblySource;
            _assetProvider = assetProvider ?? throw new ArgumentNullException(nameof(assetProvider));
            _aotAssemblyAddresses = aotAssemblyAddresses ?? Array.Empty<string>();
        }

        public async UniTask EnsureLoadedAsync(CancellationToken cancellationToken = default)
        {
            await _loadGate.WaitAsync(cancellationToken);
            try
            {
                while (_nextAssemblyIndex < _aotAssemblyAddresses.Count)
                {
                    cancellationToken.ThrowIfCancellationRequested();

                    var address = _aotAssemblyAddresses[_nextAssemblyIndex];
                    var bytes = await LoadVerifiedBytesAsync(address, cancellationToken);
                    // SuperSet: the supplemental dll is the pre-strip original, a strict superset of what
                    // shipped, so it also loads against an AOT dll that was not stripped (a dev build), unlike
                    // the stricter modes.
                    var result = RuntimeApi.LoadMetadataForAOTAssembly(bytes, HomologousImageMode.SuperSet);
                    if (result != LoadImageErrorCode.OK)
                    {
                        throw new InvalidOperationException(
                            $"LoadMetadataForAOTAssembly failed for '{address}' with {result}.");
                    }

                    _nextAssemblyIndex++;
                }
            }
            finally
            {
                _loadGate.Release();
            }
        }

        private async UniTask<byte[]> LoadVerifiedBytesAsync(string address, CancellationToken cancellationToken)
        {
            if (_assemblySource != null)
                return await _assemblySource.LoadVerifiedAsync(address, cancellationToken);

            using var handle = await _assetProvider.LoadAssetAsync<TextAsset>(address, cancellationToken);
            cancellationToken.ThrowIfCancellationRequested();
            return _verifier == null ? handle.Asset.bytes : _verifier.Verify(address, handle.Asset.bytes);
        }
    }
}
